   420	        // MOD_OPTIONS_RETROFIT_1: shipped value of every public static bool/float/int/string/enum setting, read from the field
   421	        // initialisers. MUST stay the LAST static field initialiser in this class (C# runs them in textual order).
   422	        private static readonly Dictionary<string, object> shippedDefaults = SnapshotDefaults();
   423	
   424	        private static Dictionary<string, object> SnapshotDefaults()
   425	        {
   426	            var d = new Dictionary<string, object>();
   427	            foreach (FieldInfo f in typeof(RM_HugeThingsSettings).GetFields(BindingFlags.Public | BindingFlags.Static))
   428	                if (f.FieldType == typeof(bool) || f.FieldType == typeof(float) || f.FieldType == typeof(int) || f.FieldType == typeof(string) || f.FieldType.IsEnum)
   429	                    d[f.Name] = f.GetValue(null);
   430	            return d;
   431	        }
   432	
   433	        public static void ResetFields(string[] names)
   434	        {
   435	            foreach (string n in names)
   436	            {
   437	                FieldInfo f = typeof(RM_HugeThingsSettings).GetField(n, BindingFlags.Public | BindingFlags.Static);
   438	                if (f != null && shippedDefaults.TryGetValue(n, out object v)) f.SetValue(null, v);
   439	            }
   440	        }
