   442	        private static string searchQuery = "";
   443	        private static readonly HashSet<string> collapsedSections = new HashSet<string>();
   444	
   445	        /// <summary>Section header (click to collapse), a scope tag line, and a per-section reset. Returns whether the controls
   446	        /// should draw. Scope AUDITED per setting against its read site (2026-10-10): the custom size tiers and the Large Pawns footprint and wall-break switches are latched once when the game starts (their own labels say restart), so they carry [next game start]; every other setting is read live by a tick, a job driver, a spawned building or the wake processor, none at map generation, so [now]. The giant-animals master is listed under the hitbox group but gates the other animal groups.</summary>
   447	        private static bool Group(Listing_Standard list, string title, RimMandrake.Shared.SettingScope scope, string[] names, string tagOverride = null)
   448	        {
   449	            bool searching = !string.IsNullOrWhiteSpace(searchQuery);
   450	            if (searching)
   451	            {
   452	                bool hit = RimMandrake.Shared.SettingsKitCore.Matches(title, searchQuery);
   453	                foreach (string n in names) if (!hit && RimMandrake.Shared.SettingsKitCore.Matches(n, searchQuery)) hit = true;
   454	                if (!hit) return false;
   455	            }
   456	            bool open = searching || !collapsedSections.Contains(title);
   457	            Text.Font = GameFont.Medium;
   458	            if (list.ButtonText((open ? "- " : "+ ") + title))
   459	            {
   460	                if (!collapsedSections.Remove(title)) collapsedSections.Add(title);
   461	            }
   462	            Text.Font = GameFont.Small;
   463	            if (!open) return false;
   464	            list.Label((tagOverride ?? RimMandrake.Shared.SettingsKitCore.ScopeTag(scope)) + (tagOverride != null
   465	                ? " changes take effect the next time the game starts or loads"
   466	                : scope == RimMandrake.Shared.SettingScope.NewMapsOnly ? " changes only affect maps (or planets) generated afterwards"
   467	                : scope == RimMandrake.Shared.SettingScope.NextPulse ? " changes apply the next time it is rolled or offered"
   468	                : " changes apply to what is on the map now"));
   469	            RimMandrake.Shared.SettingsKitDrawer.ResetButton(list, () => ResetFields(names));
   470	            return true;
   471	        }
   472	    }
